def word_splits(text: str, words: list[str]) -> list[str]:
    vocab = set(words)
    longest = max(map(len, vocab), default=0)
    dead = set()                         # start positions from which no split exists
    res, path = [], []

    def bt(start: int) -> bool:
        if start == len(text):
            res.append(" ".join(path))
            return True
        if start in dead:
            return False
        found = False
        for end in range(start + 1, min(len(text), start + longest) + 1):
            piece = text[start:end]
            if piece in vocab:
                path.append(piece)
                found = bt(end) or found
                path.pop()
        if not found:
            dead.add(start)              # never explore this suffix again
        return found

    bt(0)
    return res
